pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.deal(caller, amount);
        vm.prank(caller);
        c.deposit{value: amount}();

        // Note: caller may be a contract with a malicious receive that reverts
        // We call withdrawAll for the caller and track if it reverts
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // After withdrawAll() completes (whether it reverted or not), caller's credit must be 0
        // The reference contract ensures this via require(callResult), but buggy version doesn't
        uint256 callerCredit = uint256(vm.load(address(c), keccak256(abi.encode(caller, uint256(0)))));
        assertTrue(success || callerCredit == 0);
    }
}

