pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 valueSent) public {
        // Bound values to avoid overflow and unrealistic gas costs
        depositAmount = bound(depositAmount, 1, 1e18);
        vm.assume(caller != address(0) && caller != address(c));
        vm.deal(caller, depositAmount + valueSent);
        // First deposit by caller
        vm.prank(caller);
        c.deposit{value: depositAmount}();
        // Then try to withdrawAll, sending some other value (simulating a reentrancy attempt)
        vm.prank(caller);
        (bool success, ) = address(c).call{value: valueSent}(abi.encodeWithSignature("withdrawAll()"));
        // The rule: withdrawAll should never force the caller to send ETH; any call value should be rejected
        assertTrue(!success, "withdrawAll should revert when call value > 0");
    }
}

