pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(caller != address(0));
        depositAmount = bound(depositAmount, 1, 1e18);
        withdrawAmount = bound(withdrawAmount, 0, depositAmount);

        uint256 callerBalanceBefore = caller.balance;
        uint256 contractBalanceBefore = address(c).balance;

        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();

        uint256 callerBalanceAfterDeposit = caller.balance;
        uint256 contractBalanceAfterDeposit = address(c).balance;

        assertTrue(contractBalanceAfterDeposit == contractBalanceBefore + depositAmount, "Contract balance not increased by deposit");

        // Withdraw all
        vm.prank(caller);
        c.withdrawAll();

        uint256 callerBalanceAfterWithdraw = caller.balance;
        uint256 contractBalanceAfterWithdraw = address(c).balance;

        // The caller should have their deposit back (minus any gas costs in transfer version, but not in call version)
        // For the reference contract (call version), the caller gets exactly the deposited amount
        // We check that the caller's balance increased by the deposit amount (minus any gas? No, call forwards all gas)
        // In the reference, withdrawAll sends the full credit via call, which forwards all gas
        // So caller balance should be: initial + deposit - deposit (spent) + deposit (received) = initial + deposit
        // Actually: callerBalanceBefore = initial, after deposit it's initial - depositAmount, after withdraw it's initial - depositAmount + oCredit = initial
        assertTrue(callerBalanceAfterWithdraw == callerBalanceBefore, "Caller balance should be unchanged after full cycle");
        assertTrue(contractBalanceAfterWithdraw == contractBalanceBefore, "Contract balance should be unchanged after full cycle");
    }
}

