pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address to) public {
        vm.assume(from != address(0) && to != address(0) && from != to);
        vm.deal(from, 1 ether);
        vm.prank(from);
        c.deposit{value: 0.5 ether}();
        vm.prank(to);
        c.deposit{value: 0.3 ether}();
        // The sum of all credits (from and to) after deposits should equal contract balance
        // We can only read individual credits via the auto-generated getter
        // But the rule is: address(c).balance == c.credit(from) + c.credit(to) + c.credit(address(this)) + c.credit(address(0)) ...
        // However we cannot enumerate all addresses in a fuzz test, so we use a different property:
        // For a single caller: after deposit, the contract balance >= that caller's credit
        // Actually, the simplest general rule for one caller after deposit:
        vm.prank(from);
        (bool ok, ) = address(c).call{value: 0}('');
        if (ok) {
            assertTrue(c.credit(from) <= address(c).balance);
        }
    }
}

