// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount) public {
        vm.assume(caller != address(this) && caller != address(0));
        depositAmount = bound(depositAmount, 0.001 ether, 10 ether);

        // Deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();
        uint256 creditBefore = c.credit(caller);

        // Attempt withdrawal that will fail (e.g., caller is a contract that reverts on receive)
        // Use the address(this) as a fallback that reverts
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        // The call will fail if msg.sender is this test contract (which has no receive)
        // So we ensure caller is address(this) to trigger revert
        vm.assume(caller == address(this));

        uint256 creditAfter = c.credit(caller);
        assertTrue(creditBefore == creditAfter, "Credit should remain unchanged after a failed withdrawal");
    }
}
